    unsigned char *mem;
    if (size == 0) return 0;
    p = (c->hi + 15u) & ~15u;
    c->hi = p + size;
    /* I/O buffers live in the single io_mem slab.  Model blocks are
     * their own allocations; an address between two of them is a
     * 16-byte alignment hole and stays zero. */
    if (p < D4V_MODEL_BASE)
        return p;
    if (c->nspan >= 40)
        return 0;
    mem = (unsigned char *)calloc(1, (size_t)size);
    if (!mem)
        return 0;
    c->span[c->nspan].base = p;
    c->span[c->nspan].size = size;
    c->span[c->nspan].p = mem;
    c->nspan++;
