void d4vc_fill16(dec4v_ctx *c, unsigned int count, unsigned int dst,
                       unsigned int val)
{
    unsigned int i;
    for (i = 0; i < count; i++)
        d4v_st16(c, (uint32_t)(dst + 2 * i), (unsigned short)val);
}

