void d4vc_prices(dec4v_ctx *c)
{
    if (D4V_PRICE_DONE_8(&c->st, 0)) {
        unsigned int a;
        for (a = 1; a < 0x4000; a++)
            D4V_TBL_PRICE_SUM_16(&c->st, 2 * a) += D4V_TBL_PRICE_SRC_16(&c->st, 2 * a);
        D4V_PRICE_DONE_8(&c->st, 0) = 0;
    }
}

int d4vc_init_file(dec4v_ctx *c, int method, unsigned int al_in);

void uharc_dec4vc_set_flags2(void *ctx, unsigned char flags2)
{
    dec4v_ctx *c;
    c = (dec4v_ctx *)ctx;
    if (c)
        c->flags2 = flags2;
}

/* Bytes carved from 0x600000 by d4vc_init_file, plus room for the
 * file-end table decode_b bumps on afterwards.  The old 64MB arena
 * was the same bump with a zero tail; addresses past this size read
 * fx_gap, which is that tail. */
static void d4v_free_spans(dec4v_ctx *c)
{
    int i;
    for (i = 0; i < c->nspan; i++)
        free(c->span[i].p);
    c->nspan = 0;
}

int uharc_dec4vc_init(void **pctx, int method)
{
    dec4v_ctx *c;
    int rc;
    c = (dec4v_ctx *)calloc(1, sizeof(*c));
    if (!c) return 2;
    c->io_mem = (unsigned char *)calloc(1, (size_t)D4V_IO_SIZE);
    c->model_mem = 0;
    memset(c->page_span, 0xFF, sizeof(c->page_span));
    if (!c->io_mem) {
        free(c); return 2;
    }
    c->mem = NULL;
    c->st.mem = NULL;
    c->hi = 0x1000;
    c->in_buf = d4vc_alloc(c, 65536UL);
    c->out_buf = d4vc_alloc(c, 65536UL);
    if (!c->in_buf || !c->out_buf) { free(c->io_mem); free(c); return 2; }
    /* Model blocks must live ABOVE the fixed globals window (DGROUP image
     * 0x42E000-0x440000, .bss 0x440000-0x45DA00); bumping from 0x21000
     * would pave over it. 0x600000 + ~53MB footprint < 64MB arena. */
    c->hi = 0x600000UL;
    /* DGROUP static image (config bytes, pointer tables, price seeds):
     * 1:1 copy into the state's globals array, so absolute-address reads
     * match the original.  A -DD4V_AUDIT build shows the ld/st path never
     * reads an image byte before some store, but the typed accessors do
     * read this copy, so the image stays linked. */
    {
        /* The rest of the DGROUP image is unused: the lifted const
         * tables cover it, and init overwrites the pointer cells.
         * These two slices are the bytes a zeroing sweep showed the
         * corpus still reads.  See uha04_dec4_seed.c. */
        extern const unsigned char d4v_seed_436100[512];
        extern const unsigned char d4v_price_seed[34458];
        unsigned char *img;
        img = c->st.g.bytes;
        memcpy(img + 0x8100, d4v_seed_436100, 512);
        memcpy(img + 0x9966, d4v_price_seed, 34458);
    }
    rc = d4vc_init_file(c, method, 0);
    if (rc) { d4v_free_spans(c); free(c->io_mem); free(c); return rc; }
    *pctx = c;
    return 0;
}

void uharc_dec4vc_free(void *ctx)
{
    dec4v_ctx *c = (dec4v_ctx *)ctx;
    if (!c) return;
    free(c->io_mem);
    d4v_free_spans(c);
    free(c);
}

/* ---- byte pump (sub_4220B0 / sub_4221F0 / sub_422110 / sub_421F50) ---- */

/* sub_4285A0: memmove used by the 421FA0 compact path
 * (dst=t0, src=t3, n=t1; arena offsets). */
void d4v_memmove(dec4v_ctx *c, unsigned int dst, unsigned int src,
                        unsigned int n)
{
    unsigned char *d;
    unsigned char *s;
    if (n == 0)
        return;
    d = d4v_span(c, (uint32_t)dst, (int)n);
    s = d4v_span(c, (uint32_t)src, (int)n);
    if (d && s) {
        memmove(d, s, (size_t)n);
        return;
    }
    /* The two ranges are not each inside one allocation. */
    while (n) {
        *d4v_ptr(c, (uint32_t)dst) = *d4v_ptr(c, (uint32_t)src);
        dst++;
        src++;
        n--;
    }
}

/* indirect stream reader ([4370D8]): read up to n bytes to dst, return
 * bytes read (0 at EOF). 45CD24 is NOT bumped here: consumption is
 * counted per byte by sub_4220B0. */
unsigned int d4v_read_stream(dec4v_ctx *c, unsigned int dst,
                               unsigned int n, unsigned int aux)
{
    int r;
    (void)aux;
    if (c->err) return 0;
    if (n > 65536U) n = 65536U;
    if (n == 0) return 0;
    r = c->rcb(c->rctx, c->io_mem + (dst & 0xFFFFU), n);
    if (r <= 0) return 0;
    return (unsigned int)r;
}

/* sub_421F50: refill input buffer through the [4370D8] reader. */
static void d4v_refill(dec4v_ctx *c)
{
    unsigned int got;
    if (c->err) { D4V_IO_IN_VALID_32(&c->st, 0) = 0; D4V_IO_IN_POS_32(&c->st, 0) = 0; return; }
    D4V_IO_SNAP_IN_32(&c->st, 0) = D4V_IO_IN_TOTAL_32(&c->st, 0);
    D4V_IO_IN_POS_32(&c->st, 0) = 0;
    D4V_IO_SNAP_OUT_32(&c->st, 0) = D4V_IO_OUT_TOTAL_32(&c->st, 0);
    got = d4v_read_stream(c, D4V_IO_IN_PTR_32(&c->st, 0), D4V_IO_IN_CAP_32(&c->st, 0), 0);
    D4V_IO_IN_VALID_32(&c->st, 0) = got;
    if (!got) {
        D4V_IO_ERR_32(&c->st, 0) = 3;
        c->err = 3;
    }
}

/* sub_4220B0: input byte. Increments 45CD24. */
static unsigned int d4v_get_byte(dec4v_ctx *c)
{
    unsigned int pos;
    if (D4V_IO_IN_POS_32(&c->st, 0) >= D4V_IO_IN_VALID_32(&c->st, 0))
        d4v_refill(c);
    if (c->err) return 0;
    pos = D4V_IO_IN_POS_32(&c->st, 0);
    D4V_IO_IN_TOTAL_32(&c->st, 0) = D4V_IO_IN_TOTAL_32(&c->st, 0) + 1;
    D4V_IO_IN_POS_32(&c->st, 0) = pos + 1;
    return (unsigned int)c->io_mem[(D4V_IO_IN_PTR_32(&c->st, 0) + pos) & 0x3FFFFU];
}

/* forward flush used by put */
static void d4v_flush_out(dec4v_ctx *c);

/* sub_4221F0: output byte (al). Appends at 436ED4+45CD1C, bumps 45CD1C
 * and 45CD28, flushes via 422110 when 45CD1C reaches 45CD10. */
void d4v_put_byte(dec4v_ctx *c, unsigned int b)
{
    unsigned int at;
    if (c->err) return;
    at = D4V_IO_OUT_POS_32(&c->st, 0);
    c->io_mem[(D4V_IO_OUT_PTR_32(&c->st, 0) + at) & 0x3FFFFU] = (unsigned char)b;
    D4V_IO_OUT_POS_32(&c->st, 0) = at + 1;
    D4V_IO_OUT_TOTAL_32(&c->st, 0) = D4V_IO_OUT_TOTAL_32(&c->st, 0) + 1;
    if (at + 1 >= D4V_IO_OUT_CAP_32(&c->st, 0))
        d4v_flush_out(c);
}

/* sub_422110: flush output buffer through the write callback. */
static void d4v_flush_out(dec4v_ctx *c)
{
    unsigned int n = D4V_IO_OUT_POS_32(&c->st, 0);
    if (c->err) return;
    if (n) {
        if (c->wcb(c->wctx, c->io_mem + D4V_IO_OUT_PTR_32(&c->st, 0), n) != 0)
            c->err = 4;
        D4V_IO_OUT_POS_32(&c->st, 0) = 0;
    }
}

/* ---- range coder reset (sub_426F70) ----
 * NOTE: the 417DA0 decode driver calls sub_426F30, not this; 426F70
 * belongs to the 41CE30 block-driver path. Kept for reference. */
static void d4v_rc_reset(dec4v_ctx *c) /* range reset (orig d4v_426f70) */
{
    D4V_RC_CODE_LO_32(&c->st, 0) = 0;
    D4V_RC_CODE_HI_32(&c->st, 0) = 0;
    D4V_RC_CARRY_CNT_32(&c->st, 0) = 0;
    D4V_RC_PENDING_B_32(&c->st, 0) = 0;
    D4V_RC_RANGE_32(&c->st, 0) = 0xFFFFFFFFUL;
}

/* ---- range prime (sub_426F30): 45D0B8 = 0, 45D0BC = 0xFFFFFFFF, then
 * fold 5 input bytes big-endian into 45D0B8 (the decode code register).
 * Entry regs: none. */
void d4v_rc_init(dec4v_ctx *c) /* range prime: 5 bytes BE (orig d4v_426f30) */
{
    unsigned int i;
    unsigned int byte;
    unsigned int code;
    D4V_RC_CODE_32(&c->st, 0) = 0;
    D4V_RC_RANGE_32(&c->st, 0) = 0xFFFFFFFFUL;
    code = 0;
    for (i = 0; i < 5; i++) { /* loc_426F45 */
        byte = 0;
        byte = d4v_get_byte(c) & 0xFFU;
        code = D4V_RC_CODE_32(&c->st, 0);
        code = ((code << 8) | byte) & 0xFFFFFFFFUL;
        D4V_RC_CODE_32(&c->st, 0) = code;
    }
}


/* Range renormalize: while *prange < 0x1000000, shift in one byte.
 * Callers keep code/range in locals and store back to
 * D4V_RC_CODE/D4V_RC_RANGE after. (3 sites in d4v_rc_primer.) */
static void d4v_rcrenorm(dec4v_ctx *c, unsigned int *pcode, unsigned int *prange)
{
    while (*prange < 0x1000000UL) {
        unsigned int b = d4v_get_byte(c);
        *pcode = ((*pcode << 8) | (b & 0xFFU)) & 0xFFFFFFFFUL;
        *prange = (*prange << 8) & 0xFFFFFFFFUL;
    }
}

/* Range renormalize preserving caller byte register (goto-style sites).
 * pcode and prange are locals (e_ecx/e_edx or t2/t3); pbyte is the
 * caller register (e_eax/t0) clobbered with the last byte read. */
void d4v_rcrenorm_reg(dec4v_ctx *c, unsigned int *pcode, unsigned int *prange, unsigned int *pbyte)
{
    while (*prange < 0x1000000UL) {
        *pbyte = d4v_get_byte(c) & 0xFFU;
        *pcode = ((*pcode << 8) | *pbyte) & 0xFFFFFFFFUL;
        *prange = (*prange << 8) & 0xFFFFFFFFUL;
    }
}


/* ---- range reader init (sub_41F2A0) ----
 * Entry t4 = 0x45AF68 area base (constant; the second half sets it
 * explicitly and the first half uses the same [t0+4]/[t0+8] shape). */
void d4v_rc_primer(dec4v_ctx *c) /* range reader init + primer (orig d4v_41f2a0) */
{
    unsigned int rem;
    unsigned int divisor;
    unsigned int val;
    unsigned int dividend;
    unsigned int prefix_sum;
    unsigned int slot_base = D4V_RSLOT_LO;
    unsigned int saved_two;
    unsigned int counter;
    rem = 2; divisor = 2;
    D4V_RSLOT_LO_32(&c->st, 0) = rem;
    val = D4V_RC_RANGE_32(&c->st, 0);
    rem = 0;
    dividend = val; val = dividend / divisor;
    rem = 0;
    D4V_RC_RANGE_32(&c->st, 0) = val;
    divisor = val;
    val = D4V_RC_CODE_32(&c->st, 0);
    dividend = val; val = divisor ? dividend / divisor : 0; rem = divisor ? dividend % divisor : 0;
    dividend = val;
    D4V_CTX_B_45C67F_8(&c->st, 0) = (unsigned char)dividend;
    val = dividend;
    D4V_RSLOT_MID_32(&c->st, 0) = val;
    val = dividend + 1;
    D4V_RSLOT_HI_32(&c->st, 0) = val;
    val = slot_base;
    rem = d4v_slot32(c, 8u);
    val = d4v_slot32(c, 4u);
    divisor = D4V_RC_RANGE_32(&c->st, 0);
    rem = rem - val;
    val = val * divisor;
    rem = rem * divisor;
    divisor = D4V_RC_CODE_32(&c->st, 0);
    divisor = divisor - val;
    d4v_rcrenorm(c, &divisor, &rem);
    D4V_RC_CODE_32(&c->st, 0) = divisor;
    D4V_RC_RANGE_32(&c->st, 0) = rem;
    if (D4V_CTX_B_45C67F_8(&c->st, 0))
        return;
    divisor = 0;
    counter = 0;
    slot_base = D4V_RSLOT_LO;
    saved_two = 2;
    for (;;) {
        dividend = 0x800;
        D4V_RSLOT_LO_32(&c->st, 0) = dividend;
        divisor = dividend;
        dividend = 0;
        val = D4V_RC_RANGE_32(&c->st, 0);
        rem = 0;
        dividend = val; val = dividend / divisor;
        D4V_RC_RANGE_32(&c->st, 0) = val;
        divisor = val;
        val = D4V_RC_CODE_32(&c->st, 0);
        dividend = val; val = divisor ? dividend / divisor : 0;
        dividend = val & 0xFFFFU;
        D4V_RSLOT_MID_32(&c->st, 0) = dividend;
        val = dividend + 1;
        D4V_RSLOT_HI_32(&c->st, 0) = val;
        val = slot_base;
        rem = d4v_slot32(c, 8u);
        val = d4v_slot32(c, 4u);
        divisor = D4V_RC_RANGE_32(&c->st, 0);
        rem = rem - val;
        val = val * divisor;
        rem = rem * divisor;
        divisor = D4V_RC_CODE_32(&c->st, 0);
        divisor = divisor - val;
        d4v_rcrenorm(c, &divisor, &rem);
        D4V_RC_CODE_32(&c->st, 0) = divisor;
        D4V_RC_RANGE_32(&c->st, 0) = rem;
        {
            unsigned int cnt8 = counter & 0xFFU;
            val = counter;
            prefix_sum = D4V_PREFIX_SUM_TMP_32(&c->st, 0);
            D4V_RSLOT_LO_32(&c->st, 0) = saved_two;
            val = val + 0x0BU;
            dividend = (dividend << cnt8) & 0xFFFFFFFFUL;
            counter = val;
            prefix_sum = prefix_sum + dividend;
            divisor = saved_two;
            D4V_PREFIX_SUM_TMP_32(&c->st, 0) = prefix_sum;
        }
        dividend = 0;
        val = D4V_RC_RANGE_32(&c->st, 0);
        rem = 0;
        dividend = val; val = divisor ? dividend / divisor : 0;
        D4V_RC_RANGE_32(&c->st, 0) = val;
        divisor = val;
        val = D4V_RC_CODE_32(&c->st, 0);
        dividend = val; val = divisor ? dividend / divisor : 0;
        dividend = val & 0xFFFFU;
        D4V_RSLOT_MID_32(&c->st, 0) = dividend;
        val = dividend + 1;
        D4V_RSLOT_HI_32(&c->st, 0) = val;
        val = slot_base;
        rem = d4v_slot32(c, 8u);
        val = d4v_slot32(c, 4u);
        divisor = D4V_RC_RANGE_32(&c->st, 0);
        rem = rem - val;
        val = val * divisor;
        rem = rem * divisor;
        divisor = D4V_RC_CODE_32(&c->st, 0);
        divisor = divisor - val;
        d4v_rcrenorm(c, &divisor, &rem);
        D4V_RC_CODE_32(&c->st, 0) = divisor;
        D4V_RC_RANGE_32(&c->st, 0) = rem;
        if (!dividend) break;
    }
    D4V_LZP_TRIGGER_32(&c->st, 0) = D4V_PREFIX_SUM_TMP_32(&c->st, 0);
}

/* ---- shared worker helpers (single copy; draft-local copies
 * of these macros/helpers were stripped at integration) ---- */

/* Exact 32-bit arithmetic shift right (x86 SAR semantics, count masked). */
uint32_t d4v_sar(uint32_t v, unsigned int n)
{
    uint32_t s;
    n &= 31u;
    if (n == 0)
        return v & U32MASK;
    if (v & 0x80000000UL) {
        s = (0xFFFFFFFFUL << (32u - n)) & U32MASK;
        return (s | (v >> n)) & U32MASK;
    }
    return (v >> n) & U32MASK;
}

/* sub_40D570-style byte fill (t1=len, t3=val, t0=dst in the original). */
void d4v_fill(dec4v_ctx *c, unsigned int len, unsigned int dst,
                     unsigned int val)
{
    /* Storage-aware: a fill can run past the end of the globals array
     * into the arena's zero gap, which the port stands in for with one
     * byte, so it stops there. */
    uint32_t a = (uint32_t)dst;
    uint32_t n = (uint32_t)len;
    unsigned char v = (unsigned char)(val & 0xFFU);
    while (n > 0) {
        uint32_t chunk;
        uint32_t end;
        unsigned char *p;
        int si;
        p = 0;
        if (a >= D4V_GLOBALS_BASE && a < D4V_GLOBALS_END) {
            end = D4V_GLOBALS_END;
            p = c->st.g.bytes + (a - D4V_GLOBALS_BASE);
        } else if (a < D4V_IO_SIZE) {
            end = D4V_IO_SIZE;
            p = c->io_mem + a;
        } else if ((si = d4v_span_idx(c, a)) >= 0) {
            end = c->span[si].base + c->span[si].size;
            p = c->span[si].p + (a - c->span[si].base);
        } else if (a >= D4V_MODEL_BASE) {
            int i;
            uint32_t next;
            next = 0;
            for (i = 0; i < c->nspan; i++) {
                if (c->span[i].base > a) {
                    next = c->span[i].base;
                    break;
                }
            }
            /* Alignment hole between two blocks: those bytes are zero
             * and count toward the length.  Past the last block the
             * hole is the arena's infinite zero gap, written once. */
            if (next && next - a <= n) {
                n -= next - a;
                a = next;
                continue;
            }
            d4v_aud_write(a, 1);
            memset(c->fx_gap, (int)v, (size_t)1);
            break;
        } else {
            d4v_aud_write(a, 1);
            memset(c->fx_gap, (int)v, (size_t)1);
            break;
        }
        chunk = n;
        if (a + chunk > end)
            chunk = end - a;
        d4v_aud_write(a, (int)chunk);
        memset(p, (int)v, (size_t)chunk);
        a += chunk;
        n -= chunk;
    }
}

