/* Role hypothesis: LZP/literal block path. Preloads a 0x100-byte */
/* window from the dict, runs the LZP copy/match state machine over */
/* the [t2c..t5) range (tables byte_436976/byte_43691C/off_4362C0) */
/* emits the 256 buffered bytes via the model-update loop (459E58 + */
/* dict store), re-seeds the dict guard copy, rescales both models */
/* (sub_415B50/sub_415AE0), clears the hash tables, then runs the */
/* literal/match loop keyed on the 45BA18/45BA1C/45BA20 shift */
/* registers (literals via sub_417220). */
/* Entry-live regs: none (t0/t1/t2/t3/t4/t5/t6 all written */
/* before any read; no stack args; callees take none). Returns void */
/* (both callers ignore t0). */
/* Frame: 0x114 bytes + 6 pushed regs. Locals: buf[256] @ sp+0 */
/* t2c @ sp+0x100 (var_2C), t28 @ sp+0x104, t24 @ sp+0x108 */
/* t20 @ sp+0x10C, t1c @ sp+0x110. */
/* Globals touched: 433B40,45AFD0,45AFA8,45BA34,45BA24,45BA3C,45BA30 */
/* 45AF38,45C689,45C68C,T436976,459E58,433B4C,433B50,45BA18,45BA1C */
/* 45BA20,45C683,45C68F,T43691C,T4362C0,T436450,45AFC4,45AFAC,433B44 */
/* 45C692,45AF9C,433B78,433B7C,433B84,45C675,45BA28,45AFB4,45BA50 */
/* 45C67F,45CD28 (T = static image table read through arena). */
/* ------------------------------------------------------------------ */
/* Slide the unread input to the front of the buffer and pull more
 * bytes until at least n are available. A short read sets error 3. */
void d4vc_ensure_input(dec4v_ctx *c, unsigned int n)
{
    unsigned int valid;
    unsigned int pos;
    unsigned int unread;
    unsigned int base;
    unsigned int have;
    unsigned int got;
    unsigned int room;

    valid = D4V_IO_IN_VALID_32(&c->st, 0);
    pos = D4V_IO_IN_POS_32(&c->st, 0);
    unread = valid - pos;
    if (unread >= n) {
        D4V_IO_IN_VALID_32(&c->st, 0) = valid;
        return;
    }
    base = D4V_IO_IN_PTR_32(&c->st, 0);
    d4v_memmove(c, base, base + pos, unread);
    D4V_IO_SNAP_IN_32(&c->st, 0) = D4V_IO_IN_TOTAL_32(&c->st, 0);
    D4V_IO_IN_POS_32(&c->st, 0) = 0;
    D4V_IO_SNAP_OUT_32(&c->st, 0) = D4V_IO_OUT_TOTAL_32(&c->st, 0);
    have = unread;
    for (;;) {
        base = D4V_IO_IN_PTR_32(&c->st, 0);
        room = D4V_IO_IN_CAP_32(&c->st, 0) - have;
        D4V_IO_IN_VALID_32(&c->st, 0) = have;
        got = d4v_read_stream(c, base + have, room, have);
        if (got == 0) {
            D4V_IO_ERR_32(&c->st, 0) = 3;
            return;
        }
        have += got;
        if (have >= n)
            break;
    }
    D4V_IO_IN_VALID_32(&c->st, 0) = have;
}

